<?php $sections=rows('SELECT * FROM homepage_sections WHERE active=1 ORDER BY sort_order');foreach($sections as $s): ?>
<?php if($s['id']==='hero'): ?><section class="hero"><div class="hero-copy"><span class="eyebrow">THE ART OF LITTLE DETAILS</span><h1><?= nl2br(e($s['title'])) ?></h1><p><?= e($s['description']) ?></p><?php if($s['cta_text']): ?><a class="button" href="<?= e($s['cta_url']) ?>"><?= e($s['cta_text']) ?></a><?php endif ?><div class="hero-note"><span class="tiny-star">✧</span> <?= e(settings('branding')['slogan']) ?></div></div><div class="hero-photo"><img src="<?= e(image_url($s['image'])) ?>" alt="Thoughtfully chosen jewelry at M’s Charm" fetchpriority="high" width="1000" height="1000"><span class="photo-note">A little charm goes a long way.</span></div></section>
<?php elseif($s['id']==='categories'): ?><section class="section"><div class="section-heading"><div><span class="eyebrow">THE COLLECTIONS</span><h2><?= e($s['title']) ?></h2><p><?= e($s['description']) ?></p></div><a class="text-link" href="<?= e($s['cta_url']) ?>"><?= e($s['cta_text']) ?></a></div><div class="category-strip"><?php foreach(categories() as $c):if(!empty($c['parent_id']))continue; ?><a class="category-tile <?= !$c['image']?'text-category':'' ?>" href="/shop?category=<?= e($c['slug']) ?>"><?php if($c['image']): ?><img src="<?= e(image_url($c['image'])) ?>" alt="<?= e($c['name']) ?>" loading="lazy" width="400" height="450"><?php endif ?><span><?= e(category_path_name($c,categories())) ?></span></a><?php endforeach ?></div></section>
<?php elseif($s['id']==='featured'): ?><section class="section featured-section"><div class="section-heading"><div><span class="eyebrow">EVERYDAY FAVORITES</span><h2><?= e($s['title']) ?></h2><p><?= e($s['description']) ?></p></div><a class="text-link" href="<?= e($s['cta_url']) ?>"><?= e($s['cta_text']) ?></a></div><div class="product-grid"><?php foreach(products(['featured'=>1]) as $p)require ROOT.'/app/views/product-card.php'; ?></div></section>
<?php elseif($s['id']==='about'): ?><section class="story-section"><div class="story-image"><img src="<?= e(image_url($s['image'])) ?>" alt="Jewelry details, thoughtfully selected" loading="lazy" width="900" height="1000"></div><div class="story-copy"><span class="eyebrow">THE STORY BEHIND THE CHARM</span><h2><?= nl2br(e($s['title'])) ?></h2><p><?= e($s['description']) ?></p><a class="text-link" href="<?= e($s['cta_url']) ?>"><?= e($s['cta_text']) ?></a></div></section>
<?php elseif($s['id']==='promotions'): $promos=rows('SELECT * FROM promotions WHERE active=1 ORDER BY sort_order');if($promos): ?><section class="section"><div class="section-heading"><div><h2><?= e($s['title']) ?></h2><p><?= e($s['description']) ?></p></div></div><div class="promotion-grid"><?php foreach($promos as $promo): ?><article class="promotion"><?php if($promo['image']): ?><img src="<?= e(image_url($promo['image'])) ?>" alt="<?= e($promo['title']) ?>" loading="lazy"><?php endif ?><h3><?= e($promo['title']) ?></h3><p><?= e($promo['description']) ?></p><?php if($promo['cta_text']): ?><a class="button" href="<?= e($promo['cta_url']) ?>"><?= e($promo['cta_text']) ?></a><?php endif ?></article><?php endforeach ?></div></section><?php endif ?>
<?php elseif($s['id']==='reviews'): $testimonials=rows("SELECT * FROM reviews WHERE status='approved' AND featured=1 ORDER BY created_at DESC");?><section class="section reviews-home"><span class="eyebrow">FROM OUR COMMUNITY</span><h2><?= e($s['title']) ?></h2><p><?= e($s['description']) ?></p><?php if($testimonials): ?><div class="review-grid"><?php foreach($testimonials as $r): ?><blockquote><div class="stars" aria-label="<?= (int)$r['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?></div><p>“<?= e($r['comment']) ?>”</p><cite><?= e($r['name']) ?></cite></blockquote><?php endforeach ?></div><?php endif ?><a class="text-link" href="<?= e($s['cta_url']) ?>"><?= e($s['cta_text']) ?></a></section>
<?php elseif($s['id']==='social'): $socials=array_filter(settings('social'));if($socials): ?><section class="social-section"><span class="eyebrow">LET’S CONNECT</span><h2><?= e($s['title']) ?></h2><p><?= e($s['description']) ?></p><div class="social-links"><?php foreach($socials as $name=>$url): ?><a href="<?= e($url) ?>" target="_blank" rel="noopener noreferrer"><?= e(ucfirst($name)) ?></a><?php endforeach ?></div></section><?php endif ?>
<?php elseif($s['id']==='contact'): ?><section class="contact-band"><div><h2><?= e($s['title']) ?></h2><p>Questions about a piece or your order? Reach us through our social pages.</p></div><a class="button light" href="/contact">Find our socials</a></section><?php endif ?>
<?php endforeach ?>
